-- Try the SQL with the built-in test model: no key, no network. It returns
-- constants (0.5, the first option), so it can never pass for a real answer.
SELECT decide_probability('The customer requests a refund.', 'A refund is requested.', model := 'stub') AS p;

-- Real answers: register a hosted model, opt in to remote calls, and ask.
-- (export LIQUID_API_KEY=... before starting DuckDB; a DuckDB secret overrides it)
SET anofox_decide_allow_remote = true;                 -- your text goes to the provider
SELECT decide_register_model('d1:free', 'liquid');
SET anofox_decide_model = 'd1:free';

SELECT id,
       decide_probability(text, 'A refund is requested.')                                    AS p_refund,
       decide_choice(text, 'Which team owns this?', ['billing', 'defect', 'other'])          AS team,
       decide_score(text, 'How frustrated is the writer?', ['calm', 'frustrated', 'angry'])  AS frustration
FROM (VALUES (1, 'I was charged twice for my March invoice, please refund the extra 49 EUR.'),
             (2, 'The app crashes every time I open the export dialog on version 3.2.')) t(id, text);

